         m_tasks.assign(std::min(workers_count, m_inputs.size()), [this] {
             while (ProcessInput()) {}
         });
-        if (auto futures{m_thread_pool->Submit(m_tasks)}) {
+        if (auto futures{m_thread_pool->Submit(std::move(m_tasks))}) {
+            // We expect to be able to reuse the backing array.
+            Assume(m_tasks.capacity() >= std::min(workers_count, m_inputs.size()));
